from bs4 import BeautifulSoup
from pathlib import Path
import json,re,sys
pages=Path(sys.argv[1]); manifest=Path(sys.argv[2]); out=Path(sys.argv[3])
urls={int(line.split()[0]):line.split(maxsplit=1)[1] for line in manifest.read_text().splitlines() if line.strip()}
def norm(s): return re.sub(r'"'\\s+',' ',s or '').strip()
def labelled(soup,label):
    for h in soup.find_all(['h4','h3','h2']):
        if norm(h.get_text())==label:
            # first p in same parent, then next sibling/descendant
            for p in h.parent.find_all('p',recursive=True):
                t=norm(p.get_text(' ',strip=True))
                if t: return t
            for x in h.find_all_next(['p','h4','h3','h2'],limit=3):
                if x.name=='p':
                    t=norm(x.get_text(' ',strip=True))
                    if t:return t
    return None
records=[]
for i in sorted(urls):
    s=BeautifulSoup((pages/f'{i}.html').read_text(errors='ignore'),'html.parser')
    h1=s.find('h1')
    name=norm(h1.get_text(' ',strip=True) if h1 else '')
    dur=labelled(s,'Duration')
    sem=labelled(s,'Semesters')
    typ=labelled(s,'Program Type')
    elig=None
    for h in s.find_all('h2'):
        if norm(h.get_text())=='Eligibility':
            card=h.find_parent('div',class_='su-card')
            if card:
                parts=[]
                for x in card.find_all(['li','p','div'],recursive=True):
                    # only leaf-ish text to prevent duplicates
                    if x.find(['li','p','div']): continue
                    t=norm(x.get_text(' ',strip=True))
                    if t: parts.append(t)
                elig=' '.join(dict.fromkeys(parts))
                if not elig:
                    elig=norm(card.get_text(' ',strip=True)).removeprefix('Eligibility').strip()
                break
    if not elig:
        # some pages structure eligibility in a non-card section; locate heading and next section content conservatively
        for h in s.find_all(['h2','h3']):
            if norm(h.get_text()).lower()=='eligibility':
                nxt=[]
                for x in h.find_all_next(['li','p'],limit=5):
                    t=norm(x.get_text(' ',strip=True))
                    if t:nxt.append(t)
                elig=' '.join(dict.fromkeys(nxt)) or None
                break
    records.append({'index':i,'url':urls[i],'name':name,'duration':dur,'semesters':sem,'program_type':typ,'eligibility':elig,'title':norm(s.title.get_text(' ',strip=True) if s.title else '')})
out.write_text(json.dumps(records,ensure_ascii=False,indent=2))
print('records',len(records),'missing',[(r['index'],r['url'],[k for k in ('name','duration','program_type','eligibility') if not r[k]]) for r in records if any(not r[k] for k in ('name','duration','program_type','eligibility'))])
for r in records:
 print(f\"{r['index']:03d}\\t{r['name']}\\t{r['duration']}\\t{r['program_type']}\\t{r['eligibility']}\")
PY"

