python3 - "$SAGE_TMP/verification_draft.json" "$SAGE_TMP" <<'"'PY'
from pathlib import Path
import sys
src=Path(sys.argv[1]); out=Path(sys.argv[2]); max_bytes=12000
chunks=[]; cur=[]; size=0
for line in src.open():
 if cur and size+len(line.encode())>max_bytes:
  chunks.append(''.join(cur)); cur=[]; size=0
 cur.append(line); size+=len(line.encode())
if cur: chunks.append(''.join(cur))
for i,c in enumerate(chunks): (out/f'chunk.{i:02d}').write_text(c)
print('chunks',len(chunks),'bytes',sum((out/f'chunk.{i:02d}').stat().st_size for i in range(len(chunks))))
for i in range(len(chunks)): print(i,(out/f'chunk.{i:02d}').stat().st_size)
PY"

